import cv2import dlibimport osimport face_recognitionimport numpy as npdetector = dlib.get_frontal_face_detector()# Path for saving imagesnew_path = r'C:\Users\navte\Desktop\python\webcam\extracted_images'# Create directory if it doesn't existos.makedirs(new_path, exist_ok=True)captured_faces_embeddings = []face_ids = []clear_face_count = 0def save(img, name, bbox, width=180, height=227):    x, y, w, h = bbox    imgCrop = img[y:h, x:w]    if imgCrop.size == 0:        print(f"Warning: Empty image crop for {name}")        return None    imgCrop = cv2.resize(imgCrop, (width, height))    cv2.imwrite(name + ".jpg", imgCrop)    print(f"Saved: {name}.jpg")    return imgCropdef is_unique_face(face_encoding):    if not captured_faces_embeddings:        return True        face_distances = face_recognition.face_distance(captured_faces_embeddings, face_encoding)    return np.all(face_distances >= 0.6)def process_frame(frame, frame_counter):    rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)    face_locations = face_recognition.face_locations(rgb_frame)    face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)    print(f"Number of faces detected: {len(face_locations)}")    global clear_face_count    for face_encoding, face_location in zip(face_encodings, face_locations):        if is_unique_face(face_encoding):            face_id = len(captured_faces_embeddings) + 1            captured_faces_embeddings.append(face_encoding)            face_ids.append(face_id)            y1, x2, y2, x1 = face_location            imgCrop = save(frame, os.path.join(new_path, f"face_{frame_counter}_{face_id}"), (x1, y1, x2, y2))            if imgCrop is not None:                clear_face_count += 1            cv2.rectangle(frame, (x1, y1), (x2, y2), (0, 255, 0), 2)            cv2.putText(frame, f"ID: {face_id}", (x1, y1 - 10), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 255, 0), 2)        else:            y1, x2, y2, x1 = face_location            cv2.rectangle(frame, (x1, y1), (x2, y2), (0, 0, 255), 2)  # Red for non-unique faces    return framedef main():    cap = cv2.VideoCapture(0)  # Use default webcam    if not cap.isOpened():        print("Error: Failed to open webcam.")        return        frame_counter = 0        while True:        # Skip frames for faster processing        for _ in range(2):  # Adjust this value as needed            cap.grab()        ret, frame = cap.read()        if not ret:            print("Error: Failed to capture frame.")            break        # Resize the frame for faster processing        frame = cv2.resize(frame, (640, 480))        processed_frame = process_frame(frame, frame_counter)        cv2.imshow('Webcam Frame', processed_frame)                # Press 'q' to quit        if cv2.waitKey(1) & 0xFF == ord('q'):            break                frame_counter += 1    print(f"Total faces saved: {clear_face_count}")    cap.release()    cv2.destroyAllWindows()if __name__ == "__main__":    main()